const HOUR_MS = 60 * 60 * 1000;

const NOT_THROTTLED = Object.freeze({ throttled: false });

function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || 'there')
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, message.category || 'general');
}

function validateBaseUser(user) {
  if (!user || typeof user !== 'object') {
    throw new TypeError('user is required');
  }
  if (!user.id) {
    throw new TypeError('user.id is required');
  }
}

function validateMessage(message) {
  if (!message || typeof message !== 'object') {
    throw new TypeError('message is required');
  }
  if (!message.title || !message.body) {
    throw new TypeError('message.title and message.body are required');
  }
}

/**
 * Builds a notifier for one channel by composing shared send logic with a
 * channel strategy. A strategy is a plain object:
 *   channel, defaultMaxPerHour, transportName, transportError,
 *   settings(options)                     -> channel-specific config
 *   validateUser(user)                    -> throws on invalid user (optional)
 *   shouldThrottle(ctx, baseCheck)        -> throttle result (optional)
 *   format(ctx, base)                     -> channel payload built from base
 * where ctx is { user, message, options, config, now }.
 */
function createChannelNotifier(strategy, options = {}) {
  const channel = strategy.channel;
  const config = {
    ...strategy.settings(options),
    transport: options.transport || {},
    templates: options.templates || {},
    throttleStore: options.throttleStore || new Map(),
    now: options.now || (() => new Date()),
    defaultSender: options.defaultSender || 'Product Team',
    defaultLocale: options.defaultLocale || 'en-US',
    maxPerHour: options.maxPerHour || strategy.defaultMaxPerHour
  };

  const throttleKey = (user, message) => `${channel}:${user.id}:${message.category || 'general'}`;

  function baseThrottle(user, message, sendOptions) {
    if (sendOptions.force || message.priority === 'urgent') {
      return NOT_THROTTLED;
    }

    const key = throttleKey(user, message);
    const now = config.now().getTime();
    const records = (config.throttleStore.get(key) || []).filter(ts => now - ts < HOUR_MS);

    if (records.length >= config.maxPerHour) {
      return {
        throttled: true,
        reason: `${channel} hourly limit reached`,
        retryAt: new Date(records[0] + HOUR_MS).toISOString()
      };
    }
    return NOT_THROTTLED;
  }

  function baseFormat(user, message, sendOptions) {
    const title = applyTemplate(message.title, user, message);
    const body = applyTemplate(message.body, user, message);

    return {
      id: `${channel}-${user.id}-${config.now().getTime()}`,
      channel,
      locale: sendOptions.locale || user.locale || config.defaultLocale,
      title,
      body,
      preview: `${title}: ${body}`.slice(0, 120),
      metadata: {
        category: message.category || 'general',
        priority: message.priority || 'normal',
        generatedAt: config.now().toISOString()
      }
    };
  }

  function recordDelivery(user, message) {
    const key = throttleKey(user, message);
    const records = config.throttleStore.get(key) || [];
    records.push(config.now().getTime());
    config.throttleStore.set(key, records);
  }

  async function deliver(payload) {
    const send = config.transport[strategy.transportName];
    if (typeof send !== 'function') {
      throw new Error(strategy.transportError);
    }
    await send.call(config.transport, payload);
  }

  async function send(user, message, sendOptions = {}) {
    validateBaseUser(user);
    if (strategy.validateUser) {
      strategy.validateUser(user);
    }
    validateMessage(message);

    const ctx = { user, message, options: sendOptions, config, now: config.now };
    const baseCheck = () => baseThrottle(user, message, sendOptions);
    const throttle = strategy.shouldThrottle ? strategy.shouldThrottle(ctx, baseCheck) : baseCheck();
    if (throttle.throttled) {
      return {
        channel,
        status: 'throttled',
        reason: throttle.reason,
        retryAt: throttle.retryAt,
        userId: user.id
      };
    }

    const formatted = strategy.format(ctx, baseFormat(user, message, sendOptions));
    await deliver(formatted);
    recordDelivery(user, message);

    return {
      channel,
      status: 'sent',
      userId: user.id,
      id: formatted.id,
      preview: formatted.preview
    };
  }

  return { channel, send, config };
}

module.exports = { createChannelNotifier };
const { createChannelNotifier } = require('./createChannelNotifier');

function blocksFor(base, mention) {
  return [
    { type: 'section', text: { type: 'mrkdwn', text: `${mention}*${base.title}*` } },
    { type: 'section', text: { type: 'mrkdwn', text: base.body } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: `Category: ${base.metadata.category}` }] }
  ];
}

const slackStrategy = {
  channel: 'slack',
  defaultMaxPerHour: 20,
  transportName: 'slack',
  transportError: 'slack transport is not configured',

  settings: options => ({
    defaultWorkspace: options.defaultWorkspace || 'main',
    defaultChannel: options.defaultChannel || '#general'
  }),

  validateUser(user) {
    if (!user.slackId && !user.slackChannel) {
      throw new TypeError('user.slackId or user.slackChannel is required for Slack notifications');
    }
  },

  shouldThrottle({ options }, baseCheck) {
    if (options.threadTs) {
      return { throttled: false };
    }
    return baseCheck();
  },

  format({ user, options, config }, base) {
    const channel = options.channel || user.slackChannel || config.defaultChannel;
    const mention = user.slackId ? `<@${user.slackId}> ` : '';
    const text = `${mention}*${base.title}*\n${base.body}`;

    return {
      ...base,
      workspace: user.slackWorkspace || config.defaultWorkspace,
      channel,
      threadTs: options.threadTs || null,
      text,
      blocks: blocksFor(base, mention),
      preview: text.replace(/\*/g, '').slice(0, 120)
    };
  }
};

module.exports = options => createChannelNotifier(slackStrategy, options);
const { createChannelNotifier } = require('./createChannelNotifier');

const E164 = /^\+[1-9]\d{6,14}$/;

function truncate(value, segmentLength) {
  if (value.length <= segmentLength) {
    return value;
  }
  return `${value.slice(0, segmentLength - 1)}…`;
}

const smsStrategy = {
  channel: 'sms',
  defaultMaxPerHour: 4,
  transportName: 'sms',
  transportError: 'sms transport is not configured',

  settings: options => ({
    senderId: options.senderId || 'APP',
    segmentLength: options.segmentLength || 140
  }),

  validateUser(user) {
    if (!user.phone || !E164.test(user.phone)) {
      throw new TypeError('user.phone must be E.164 for SMS notifications');
    }
  },

  shouldThrottle({ user, message }, baseCheck) {
    const base = baseCheck();
    if (base.throttled) {
      return base;
    }
    if (message.category === 'marketing' && !user.smsOptIn) {
      return { throttled: true, reason: 'user has not opted into marketing SMS', retryAt: null };
    }
    return { throttled: false };
  },

  format({ user, message, config }, base) {
    const prefix = message.priority === 'urgent' ? 'URGENT: ' : '';
    const text = truncate(`${prefix}${base.title} - ${base.body}`, config.segmentLength);

    return {
      ...base,
      to: user.phone,
      from: config.senderId,
      text,
      segments: Math.ceil(text.length / config.segmentLength),
      preview: text
    };
  }
};

module.exports = options => createChannelNotifier(smsStrategy, options);
const registry = {
  email: require('./emailChannel'),
  sms: require('./smsChannel'),
  slack: require('./slackChannel'),
  inapp: require('./inAppChannel')
};

function createNotifier(channel, options = {}) {
  const createChannel = registry[channel];
  if (!createChannel) {
    throw new TypeError(`unknown notification channel: ${channel}`);
  }
  return createChannel(options);
}

function createAllNotifiers(options = {}) {
  return Object.keys(registry).reduce((all, channel) => {
    all[channel] = createNotifier(channel, options);
    return all;
  }, {});
}

module.exports = {
  createNotifier,
  createAllNotifiers,
  registry
};
